Object.assign(window.STUDY_EXAMS,{"dta301_su24":{"title":"SU24 · FE — 57 câu luyện","short":"SU24 · FE","storageKey":"dta301_unified_su24_60_v2","legacyKey":"dta301_unified_su24_60_v1","notice":"57 câu đã có đáp án để luyện tập và thi thử. 3 câu còn cần làm rõ được chuyển sang danh sách Câu cần xác minh. Giữ số câu gốc, giải thích, nguồn và mẹo nhớ.","questions":[{"id":1,"stem":"Which of the following are attributes stand out as defining Big Data characteristics?","options":["Huge volume","Complexity of type and structure","Speed of new data creation and growth","All of the others"],"image":"assets/dta301/su24/01.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[3],"chapter":1,"sourceTerm":"volume","detail":"Ba đặc trưng cốt lõi là Volume, Variety và Velocity.","trick":"3V: Lượng – Loại – Tốc độ.","why":["Volume đúng nhưng chỉ là một đặc trưng.","Độ đa dạng kiểu/cấu trúc tương ứng Variety, chưa đủ cả ba.","Tốc độ tạo dữ liệu tương ứng Velocity, chưa đủ cả ba.","Bao gồm đủ ba đặc trưng A, B và C."],"caution":"","topic":"Big Data và vai trò","gradable":true,"reference":"Sách chương 1, trang 2 (PDF trang 22) · Slide chương 1, slide 5","bookPage":2,"pdfPage":22,"slideNumbers":[5],"keywords":["defining","Big Data characteristics"]},{"id":3,"stem":"is textual data with erratic data formats that can be formatted with effort, tools, and time (for instance, web clickstream data that may contain inconsistencies in data values and formats)","options":["Structured data","Semi-structured data","Quasi-structured data","Unstructured data"],"image":"assets/dta301/su24/03.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[2],"chapter":1,"sourceTerm":"Quasi-structured","detail":"Quasi-structured là text có định dạng thất thường, có thể định cấu trúc bằng thời gian, công cụ và công sức; ví dụ clickstream không nhất quán.","trick":"Quasi = gần có cấu trúc, nhưng lộn xộn.","why":["Structured có schema rõ và nhất quán.","Semi-structured có dấu hiệu cấu trúc như tags/hierarchy, không khớp định nghĩa erratic trong sách.","Đúng định nghĩa và ví dụ clickstream được nêu.","Unstructured không có mô hình tổ chức rõ như văn bản tự do, ảnh/video."],"caution":"","topic":"Big Data và vai trò","gradable":true,"reference":"Sách chương 1, trang 6 (PDF trang 26) · Slide chương 1, slide 10","bookPage":6,"pdfPage":26,"slideNumbers":[10],"keywords":["erratic data formats","formatted with effort"]},{"id":4,"stem":"Which of data types is containing a defined data type, format, and structure (that is, transaction data, online analytical processing data cubes...)?","options":["Structured data","Semi-structured data","Quasi-structured data","Unstructured data"],"image":"assets/dta301/su24/04.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":1,"sourceTerm":"","detail":"Structured data có kiểu, định dạng và cấu trúc xác định; ví dụ dữ liệu giao dịch hoặc OLAP cubes.","trick":"Structured = schema rõ, hàng/cột rõ.","why":["Đúng mô tả dữ liệu có schema xác định.","Semi-structured có tags/hierarchy nhưng không phải cấu trúc cứng hoàn chỉnh như mô tả.","Quasi-structured có định dạng thất thường cần xử lý mới tổ chức lại được.","Unstructured thiếu cấu trúc vốn có rõ ràng như bảng."],"caution":"","topic":"Big Data và vai trò","gradable":true,"bookPage":6,"pdfPage":26,"slideNumbers":[10],"reference":"Sách chương 1, trang 6 (PDF trang 26) · Slides chương 1, slide 10","keywords":["defined data type, format, and structure"]},{"id":5,"stem":"tends to use disaggregated data in a more forward-looking, exploratory way, focusing on analyzing the present and enabling informed decisions about the future","options":["Data Science","Business Intelligence","Data warehouse","Data exploratory","Data exploratory and analytics"],"image":"assets/dta301/su24/05.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":1,"sourceTerm":"","detail":"Đoạn so sánh BI với Data Science mô tả Data Science dùng dữ liệu ít tổng hợp hơn và hướng khám phá, hiện tại/tương lai.","trick":"DS hỏi how/why và nhìn tới; BI thường when/where và báo cáo.","why":["Khớp mô tả Data Science trong mục BI Versus Data Science.","BI trong so sánh này thiên về báo cáo, truy vấn và dữ liệu lịch sử tổng hợp.","Data warehouse là hệ thống/kho lưu trữ, không phải kiểu phân tích được mô tả.","Không phải tên lĩnh vực được dùng trong đoạn định nghĩa.","Không phải thuật ngữ mà sách dùng làm vế đối chiếu với BI."],"caution":"Đây là phân biệt theo cách trình bày của sách. BI hiện đại cũng có thể hỗ trợ phân tích hướng tương lai; không xem ranh giới này là tuyệt đối.","topic":"Big Data và vai trò","gradable":true,"bookPage":12,"pdfPage":32,"slideNumbers":[14],"reference":"Sách chương 1, trang 12 (PDF trang 32) · Slide chương 1, slide 14","keywords":["disaggregated data","forward-looking, exploratory"]},{"id":6,"stem":"The data-conditioning step is usually performed only by the following member, except:","options":["The data owners","A data engineer","A database administrator","A programmer"],"image":"assets/dta301/su24/06.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[3],"chapter":2,"sourceTerm":"data-conditioning step","detail":"Theo danh sách trong sách, conditioning thường gắn với IT, data owners, DBA và data engineer. Programmer không được liệt kê thành vai trò riêng trong câu này.","trick":"Owner – DBA – Engineer; vẫn cần Data Scientist tham gia.","why":["Data owners được sách liệt kê.","Data engineer được sách liệt kê.","DBA được sách liệt kê.","Không được liệt kê riêng trong nhóm vai trò này."],"caution":"Đây là câu nhận diện danh sách của sách. Lập trình viên vẫn có thể làm conditioning; từ “only” trong câu không nên hiểu là cấm vai trò khác. Sách nhấn mạnh phải có Data Scientist tham gia.","topic":"Data Analytics Lifecycle","gradable":true,"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2","bookPage":40,"pdfPage":60,"slideNumbers":[],"keywords":["data-conditioning","member","except"]},{"id":7,"stem":"When pursuing the data visualization approach with a data visualization tool or statistical package, the following guidelines and considerations are recommended, except:","options":["Review data to ensure that calculations remained consistent within columns or across tables for a given data field","Does the data distribution stay consistent over all the data? If not, what kinds of actions should be taken to address this problem?","Assess the granularity of the data, the range of values, and the level of aggregation of the data.","Assess the size of the data, the variety, range of values, and the level of aggregation of the data."],"image":"assets/dta301/su24/07.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[3],"chapter":2,"sourceTerm":"","detail":"Danh sách Survey and Visualize trong sách nêu tính nhất quán phép tính, phân bố dữ liệu và granularity/range/aggregation. D thay granularity bằng size/variety nên không khớp danh sách được trích.","trick":"Trong đoạn này nhớ granularity = độ chi tiết, không chỉ kích thước.","why":["Được liệt kê: kiểm tra phép tính có nhất quán theo cột/bảng không.","Được liệt kê: kiểm tra phân bố có nhất quán qua dữ liệu không.","Đúng câu sách về granularity, range và aggregation.","Là ngoại lệ theo danh sách được trích; thay granularity bằng size/variety."],"caution":"D không phải lời khuyên sai trong thực hành. Đáp án D dựa trên danh sách nguyên văn của tài liệu, không có nghĩa không cần quan tâm kích thước hay độ đa dạng.","topic":"Data Analytics Lifecycle","gradable":true,"bookPage":41,"pdfPage":61,"slideNumbers":[],"reference":"Sách chương 2, trang 41 (PDF trang 61) · Slides chương 2","keywords":["data visualization","guidelines","except"]},{"id":8,"stem":"Which of the following phase teams begin forming ideas about which data to keep and which data to transform or discard?","options":["Data visualization","Data conditioning","Learning About the Data","Prepare analytics sandbox"],"image":"assets/dta301/su24/08.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":2,"sourceTerm":"","detail":"Data Conditioning quyết định giữ dữ liệu nào, biến đổi dữ liệu nào và bỏ dữ liệu nào vì những quyết định đó ảnh hưởng phân tích sau.","trick":"Giữ – biến đổi – bỏ = conditioning.","why":["Visualization khảo sát bằng đồ thị, không phải tên bước trong đoạn trích.","Đúng bước được sách mô tả.","Learning About the Data là tìm hiểu nội dung/nguồn, còn quyết định giữ/sửa/bỏ trong đoạn là conditioning.","Sandbox là môi trường làm việc, không phải bước quyết định chất lượng/chọn dữ liệu."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"bookPage":40,"pdfPage":60,"slideNumbers":[19],"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2, slide 19","keywords":["phase","keep","transform or discard"]},{"id":9,"stem":"In the data conditioning phase, data science team should consider the following issues, except:","options":["Assess the consistency of the data types","Review the content of data columns or other inputs, and check to ensure they make sense","Look for any evidence of systematic error","Categorize data into classes"],"image":"assets/dta301/su24/09.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[3],"chapter":2,"sourceTerm":"","detail":"Conditioning xem xét tính nhất quán kiểu dữ liệu, nội dung có hợp lý và lỗi hệ thống. Gán lớp là nhiệm vụ classification trong ngữ cảnh các lựa chọn này.","trick":"Conditioning sửa chất lượng; Classification gán nhãn.","why":["Là nội dung conditioning.","Là nội dung conditioning.","Là nội dung conditioning.","Không thuộc danh sách kiểm tra conditioning đang được trích."],"caution":"Trong thực hành, mã hóa nhóm/discretization vẫn có thể nằm ở chuẩn bị dữ liệu. D là ngoại lệ theo danh sách trong sách, không phải lệnh cấm tạo biến categorical.","topic":"Data Analytics Lifecycle","gradable":true,"bookPage":40,"pdfPage":60,"slideNumbers":[19],"reference":"Sách chương 2, trang 40 (PDF trang 60) · Slides chương 2, slide 19","keywords":["data conditioning","except"]},{"id":10,"stem":"Who in an analytics project will provides business domain expertise based on a deep understanding of the data, key performance indicators (KPIs), key metrics, and business intelligence from a reporting perspective?","options":["Business user","Project sponsor","Business intelligence analyst","Project Manager"],"image":"assets/dta301/su24/10.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[2],"chapter":2,"sourceTerm":"","detail":"BI Analyst cung cấp chuyên môn miền dựa trên dữ liệu, KPI, metrics và góc nhìn báo cáo.","trick":"KPI + reporting + dashboard = BI Analyst.","why":["Business User hiểu nghiệp vụ và hưởng lợi từ kết quả, nhưng đoạn có KPI/reporting đang định nghĩa BI Analyst.","Sponsor bảo trợ dự án và xét giá trị/rủi ro/ROI.","Khớp chính xác vai trò có KPI, metrics và reporting perspective.","Project Manager quản lý mốc, tiến độ, chất lượng và ngân sách."],"caution":"","topic":"Data Analytics Lifecycle","gradable":true,"bookPage":27,"pdfPage":47,"slideNumbers":[4],"reference":"Sách chương 2, trang 27 (PDF trang 47) · Slides chương 2, slide 4","keywords":["business domain expertise","KPIs","reporting perspective"]},{"id":11,"stem":"The _____is that there is a difference between two samples","options":["alternative hypothesis (HA)","null hypothesis (HO)","null hypothesis (HA)","alternative hypothesis (HO)"],"image":"assets/dta301/su24/11.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":3,"sourceTerm":"","detail":"Với kiểm định khác biệt hai phía, HA nói có khác biệt giữa hai tổng thể; H0 nói không có khác biệt.","trick":"A trong HA = Alternative = có khác biệt.","why":["Đúng tên và ký hiệu của giả thuyết đối.","H0 là giả thuyết không, thường biểu thị không khác biệt.","Tên null nhưng ký hiệu HA không khớp.","Tên alternative nhưng ký hiệu H0 không khớp."],"caution":"Nói chặt hơn là khác biệt tham số tổng thể, không phải chỉ quan sát hai mẫu khác nhau. Hai mẫu có thể khác do ngẫu nhiên ngay cả khi H0 đúng.","topic":"R và thống kê cơ bản","gradable":true,"bookPage":102,"pdfPage":122,"slideNumbers":[69,70],"reference":"Sách chương 3, trang 102 (PDF trang 122) · Slides chương 3, slide 69, 70","keywords":["difference between two samples"]},{"id":13,"stem":"Does Student's t-test assumes that distributions of the two populations have equal but unknown variances?","options":["Yes","No"],"image":"assets/dta301/su24/13.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":3,"sourceTerm":"Student","detail":"Student t-test hai mẫu gộp giả định phương sai bằng nhau nhưng chưa biết.","trick":"Student = Same variance; Welch = phương sai có thể khác.","why":["Đúng cho pooled two-sample Student t-test.","Sai với giả định được hỏi."],"caution":"Không suy rộng giả định bằng phương sai này cho mọi dạng t-test.","topic":"R và thống kê cơ bản","gradable":true,"reference":"Sách chương 3, trang 104 (PDF trang 124) · Slide chương 3, slide 2, 73, 74","bookPage":104,"pdfPage":124,"slideNumbers":[2,73,74],"keywords":["Student's t-test","equal but unknown variances"]},{"id":14,"stem":"The expected defaults for headers, column separators, and decimal point notations of read.delim2() function are ____.","options":["header=FALSE, sep=\"\", dec=\".\"","header=TRUE, sep=\",\", dec=\".\"","header=TRUE, sep=\";\", dec=\",\"","header=TRUE, sep=\"\\t\", dec=\".\"","header=TRUE, sep=\"\\t\", dec=\",\""],"image":"assets/dta301/su24/14.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[4],"chapter":3,"sourceTerm":"read.delim","detail":"read.delim2 giữ header=TRUE và tab nhưng đổi dec thành dấu phẩy.","trick":"Hàm có số 2: thập phân dùng phẩy.","why":["header=FALSE, separator rỗng và dấu chấm thập phân đều không phải bộ mặc định của read.delim2.","Dấu phẩy phân cột và dấu chấm thập phân là kiểu read.csv.","Đây là read.csv2, dùng chấm phẩy phân cột.","Đây là read.delim thông thường.","Đúng bộ mặc định read.delim2."],"caution":"","topic":"R và thống kê cơ bản","gradable":true,"reference":"Sách chương 3, trang 69 (PDF trang 89) · Slide chương 3, slide 15, 16","bookPage":69,"pdfPage":89,"slideNumbers":[15,16],"keywords":["defaults","read.delim2()"]},{"id":16,"stem":"The dataset has four columns, with Student ID first. Does this exclude Student ID from k-means input?\nkmdata_orig = as.matrix(grade_input[,c(\"Student\",\"English\",\"Math\",\"Science\")])\nkmdata <- kmdata_orig[,2:4]","options":["True","False"],"image":"assets/dta301/su24/16.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":4,"sourceTerm":"Student","detail":"Chỉ số [,2:4] giữ mọi dòng và ba cột 2 đến 4, nên loại Student ở cột 1.","trick":"Trước dấu phẩy = dòng; sau = cột.","why":["Đúng thao tác loại cột ID khỏi đầu vào khoảng cách.","Sai vì cột 1 không nằm trong dải 2:4."],"caution":"Nếu Student là chuỗi, as.matrix trên cả data frame có thể ép mọi cột sang character. Sau khi bỏ ID vẫn cần bảo đảm kmdata là numeric trước kmeans. Câu chỉ hỏi việc loại cột ID.","topic":"Clustering","gradable":true,"reference":"Sách chương 4, trang 116 (PDF trang 136) · Slide chương 4, slide 2, 19, 22","bookPage":116,"pdfPage":136,"slideNumbers":[2,19,22],"keywords":["Student ID","exclude","[,2:4]"]},{"id":17,"stem":"k clusters can be identified in a given dataset, but we should know what value of k should be selected. Which of the followings is NOT a method to verify the k cluster? Ble","options":["We should know how much better or worse having k clusters versus k - 1 or k + 1 clusters would be in explaining the structure of the data","We use a heuristic using the Within Sum of Squares (WSS) metric is examined to determine a reasonably optimal value of k.","The value of k can be chosen based on a reasonable guess or some predefined requirement.","We should base on the size of dataset and analysis requirements."],"image":"assets/dta301/su24/17.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[3],"chapter":4,"sourceTerm":"reasonable guess","detail":"Sách nêu chọn theo phỏng đoán/yêu cầu định trước và đánh giá bằng so sánh k, WSS. Không nêu kích thước dữ liệu là tiêu chí đủ để xác minh k.","trick":"Kiểm tra k bằng cấu trúc cụm/WSS, đừng lấy số dòng làm số cụm.","why":["So sánh k với k−1 và k+1 giúp đánh giá cấu trúc cụm.","WSS là tiêu chí được sách sử dụng.","Là cách khởi chọn k được sách chấp nhận khi có yêu cầu định trước.","Chỉ kích thước bộ dữ liệu không xác minh được cấu trúc hoặc k tối ưu."],"caution":"Từ “verify” chưa thật chặt: C là cách chọn ban đầu hơn là kiểm chứng. D là ngoại lệ theo danh sách trong slide 17.","topic":"Clustering","gradable":true,"reference":"Sách chương 4, trang 123 (PDF trang 143) · Slide chương 4, slide 17","bookPage":123,"pdfPage":143,"slideNumbers":[17],"keywords":["NOT","verify the k cluster"]},{"id":18,"stem":"Which of the following is an analytical technique that, for a chosen value of k, identifies k clusters of objects based on the objects’ proximity to the center of the k groups?","options":["K-means","K-modes","Hierarchical agglomerative clustering","Density clustering methods"],"image":"assets/dta301/su24/18.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":4,"sourceTerm":"","detail":"K-means nhận số cụm k và gán các điểm vào tâm cụm gần nhất rồi cập nhật tâm.","trick":"K + means (trung bình tâm) = k-means.","why":["Đúng phương pháp dựa trên khoảng cách đến tâm trung bình.","K-modes dành cho categorical, dùng mode và số thuộc tính khác nhau.","Hierarchical agglomerative tạo cây phân cấp bằng gộp cụm dần.","Density methods dựa trên vùng mật độ, không định nghĩa bằng k tâm trung bình."],"caution":"","topic":"Clustering","gradable":true,"bookPage":118,"pdfPage":138,"slideNumbers":[11,12],"reference":"Sách chương 4, trang 118 (PDF trang 138) · Slides chương 4, slide 11, 12","keywords":["k clusters","proximity to the center"]},{"id":19,"stem":"Which is a commonly used method for clustering categorical data based on the number of differences in the respective components of the attributes?","options":["K-means","K-modes","Partitioning around Medoids (PAM)"],"image":"assets/dta301/su24/19.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":4,"sourceTerm":"","detail":"K-modes phân cụm categorical bằng số thành phần thuộc tính khác nhau, cập nhật đại diện theo mode.","trick":"Categorical → mode; numeric → mean.","why":["K-means dùng mean và khoảng cách cho biến số, không phù hợp trực tiếp với categorical.","Đúng thuật toán được mô tả trong sách.","PAM dùng medoid là một quan sát thật đại diện cụm; không phải thuật toán định nghĩa trong câu."],"caution":"","topic":"Clustering","gradable":true,"bookPage":134,"pdfPage":154,"slideNumbers":[33],"reference":"Sách chương 4, trang 134 (PDF trang 154) · Slides chương 4, slide 33","keywords":["clustering categorical data","number of differences"]},{"id":20,"stem":"In which step of the k-means algorithm do we choose the value of k and the k initial guesses for the centroids?","options":["Step 1","Step 2","Step 3","Step 4"],"image":"assets/dta301/su24/20.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":4,"sourceTerm":"initial guesses","detail":"Bước 1 khởi tạo số cụm k và k tâm ban đầu.","trick":"K-means: Chọn – Gán – Tính tâm – Lặp.","why":["Bước khởi tạo k và centroids.","Bước 2 tính khoảng cách, gán điểm vào cụm.","Bước 3 tính lại tâm.","Bước 4 lặp bước gán và tính tâm."],"caution":"","topic":"Clustering","gradable":true,"reference":"Sách chương 4, trang 120 (PDF trang 140) · Slide chương 4, slide 12","bookPage":120,"pdfPage":140,"slideNumbers":[12],"keywords":["k-means","value of k","initial guesses"]},{"id":21,"stem":"What measures the difference in the probability of X and Y appearing together in the dataset compared to what would be expected if X and Y were statistically independent of each other? A Lift","options":["Lift","Leverage","Confidence","Support"],"image":"assets/dta301/su24/21.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":5,"sourceTerm":"leverage","detail":"Leverage = P(X∩Y) − P(X)P(Y), đo chênh lệch xác suất so với độc lập.","trick":"Leverage = trừ / “difference”.","why":["Lift là tỷ số.","Leverage đúng công thức hiệu xác suất.","Confidence là xác suất điều kiện.","Support là xác suất đồng xuất hiện thực tế."],"caution":"","topic":"Association Rules","gradable":true,"reference":"Sách chương 5, trang 142 (PDF trang 162) · Slide chương 5, slide 16","bookPage":142,"pdfPage":162,"slideNumbers":[16],"keywords":["difference in the probability","statistically independent"]},{"id":22,"stem":"If 80% of all transactions contain itemset {bread}, then the support of {bread} is ____.","options":["0.8","0.2","80","20"],"image":"assets/dta301/su24/22.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"support","detail":"Support là tỷ lệ giao dịch chứa itemset: 80/100=0.8.","trick":"Phần trăm chia 100 thành tỷ lệ.","why":["0.8 tương ứng 80%.","0.2 là tỷ lệ không chứa bread trong tình huống này.","80 là số phần trăm, không phải support dạng tỷ lệ.","20 không biểu diễn support đã cho."],"caution":"","topic":"Association Rules","gradable":true,"reference":"Sách chương 5, trang 139 (PDF trang 159) · Slide chương 5, slide 7","bookPage":139,"pdfPage":159,"slideNumbers":[7],"keywords":["80%","support"]},{"id":23,"stem":"If {bread,eggs,milk} has support 0.15 and {bread,eggs} also has support 0.15, the confidence of rule {bread,eggs} → {milk} is ____.","options":["1.0","0.15","0.1","100"],"image":"assets/dta301/su24/23.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"","detail":"Confidence(X→Y)=Support(X∪Y)/Support(X). Ở đây 0.15/0.15=1.0, tức 100%.","trick":"Confidence = phần chứa cả / phần đã có vế trái.","why":["Đúng 1.0 tương ứng xác suất có milk khi đã có bread và eggs là 100%.","0.15 là support, chưa lấy tỷ số.","0.1 không bằng 0.15/0.15.","100 là trị số phần trăm; dạng tỷ lệ như các lựa chọn số còn lại phải viết 1.0 hoặc ghi rõ 100%."],"caution":"","topic":"Association Rules","gradable":true,"bookPage":141,"pdfPage":161,"slideNumbers":[15],"reference":"Sách chương 5, trang 141 (PDF trang 161) · Slides chương 5, slide 15","keywords":["support 0.15","confidence","{bread,eggs} → {milk}"]},{"id":24,"stem":"A frequent itemset has items that appear together often enough. The term “often enough\" is formally defined with a criterion","options":["minimum support","maximum support","support enough","threshold"],"image":"assets/dta301/su24/24.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"minimum support","detail":"Frequent itemset có support đạt ít nhất ngưỡng minimum support.","trick":"Frequent = Support ≥ MinSupport.","why":["Tên đầy đủ của tiêu chí xác định frequent itemset.","Maximum support không phải ngưỡng tối thiểu yêu cầu.","Không phải thuật ngữ chuẩn.","Threshold quá chung; tên cụ thể đúng là minimum support."],"caution":"","topic":"Association Rules","gradable":true,"reference":"Sách chương 5, trang 139 (PDF trang 159) · Slide chương 5, slide 8, 11, 12","bookPage":139,"pdfPage":159,"slideNumbers":[8,11,12],"keywords":["frequent itemset","often enough"]},{"id":25,"stem":"Association rules is an. learning method often used to discover interesting relationships hidden in a large dataset","options":["unsupervised and descriptive","supervised and descriptive","unsupervised and predictive","supervised and predictive"],"image":"assets/dta301/su24/25.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":5,"sourceTerm":"","detail":"Association rules không dùng nhãn đích đã biết và mô tả các quan hệ đồng xuất hiện ẩn trong dữ liệu.","trick":"Association: không nhãn + mô tả quan hệ.","why":["Đúng kết hợp unsupervised và descriptive.","Supervised cần biến đích/nhãn, không phải cách khai thác luật ở đây.","Có thể dùng luật hỗ trợ dự báo nhưng phân loại của kỹ thuật trong sách là descriptive.","Sai cả hai thuộc tính theo định nghĩa được hỏi."],"caution":"","topic":"Association Rules","gradable":true,"bookPage":138,"pdfPage":158,"slideNumbers":[4,5],"reference":"Sách chương 5, trang 138 (PDF trang 158) · Slides chương 5, slide 4, 5","keywords":["Association rules","learning method","relationships"]},{"id":26,"stem":"Which of the following is an analytical technique used to model the relationship between several input variables and a continuous outcome variable?","options":["Linear regression","K-means","Association rules","Decision trees"],"image":"assets/dta301/su24/26.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"continuous outcome","detail":"Linear regression mô hình hóa quan hệ giữa các biến đầu vào và một biến đáp ứng liên tục.","trick":"Outcome là số liên tục → linear regression.","why":["Đúng định nghĩa mô hình được nêu.","K-means không có biến đích liên tục cần dự đoán.","Association rules tìm đồng xuất hiện itemsets.","Regression trees cũng dự đoán số được; trong câu định nghĩa chương Regression, A là đáp án trực tiếp."],"caution":"Decision trees có cả regression trees. Không học rằng cây chỉ dự đoán được categorical; A là lựa chọn theo định nghĩa được trích.","topic":"Regression","gradable":true,"reference":"Sách chương 6, trang 162 (PDF trang 182) · Slide chương 6, slide 4","bookPage":162,"pdfPage":182,"slideNumbers":[4],"keywords":["several input variables","continuous outcome"]},{"id":27,"stem":"What is a common technique to estimate the parameters in linear regression model?","options":["Ordinary Least Squares (OLS)","Minimum confidence","Leverage","Within Sum of Squares"],"image":"assets/dta301/su24/27.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"ordinary least squares","detail":"OLS ước lượng hệ số bằng cách tối thiểu tổng bình phương sai số.","trick":"Least Squares = ít tổng bình phương sai số nhất.","why":["Đúng phương pháp ước lượng tuyến tính phổ biến.","Minimum confidence là ngưỡng association rules.","Leverage là chỉ tiêu khác, không phải phương pháp ước lượng hệ số.","WSS đánh giá độ chặt cụm k-means."],"caution":"","topic":"Regression","gradable":true,"reference":"Sách chương 6, trang 163 (PDF trang 183) · Slide chương 6, slide 8","bookPage":163,"pdfPage":183,"slideNumbers":[8],"keywords":["estimate the parameters","linear regression"]},{"id":28,"stem":"Which is the value where the likelihood function is based on the parameters in the specified logistic mode?","options":["The null deviance","The residual deviance","The pseudo-R2","The different deviance"],"image":"assets/dta301/su24/28.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":6,"sourceTerm":"residual deviance","detail":"Residual deviance đánh giá mô hình đã lắp với các tham số của mô hình logistic được chỉ định.","trick":"Residual = mô hình đã fitted; Null = chỉ intercept.","why":["Null deviance thuộc mô hình chỉ intercept.","Đúng deviance của mô hình với các predictors đã chọn.","Pseudo-R² là thước đo suy ra từ so sánh mức phù hợp.","Không phải tên chỉ tiêu chuẩn được dùng ở đây."],"caution":"","topic":"Regression","gradable":true,"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slide chương 6, slide 43, 46","bookPage":183,"pdfPage":203,"slideNumbers":[43,46],"keywords":["likelihood function","parameters","logistic"]},{"id":29,"stem":"____ value near 1 indicates a good fit over the simple null model.","options":["A pseudo-R2","The null deviance","The residual deviance","The empty deviance","The different deviance"],"image":"assets/dta301/su24/29.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"","detail":"Pseudo-R² theo sách = 1 − residual deviance/null deviance. Gần 1 cho thấy cải thiện lớn so với intercept-only model.","trick":"Pseudo-R² gần 1: fitted tốt hơn null theo chỉ số này.","why":["Đúng thước đo tương tự R² so với null model.","Null deviance không có chuẩn “gần 1 là tốt” này.","Residual deviance không được diễn giải tốt chỉ vì gần 1; còn phụ thuộc dữ liệu/df.","Không phải thuật ngữ chuẩn của output trong sách.","Không phải tên chỉ tiêu được định nghĩa ở đây."],"caution":"Có nhiều định nghĩa pseudo-R². Không diễn giải nó như tỷ lệ phương sai được giải thích chính xác như R² tuyến tính, và không bỏ qua kiểm định/đánh giá ngoài mẫu.","topic":"Regression","gradable":true,"bookPage":183,"pdfPage":203,"slideNumbers":[43],"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slides chương 6, slide 43","keywords":["near 1","good fit","null model"]},{"id":30,"stem":"In logistic regression, ____ is defined to be −2 × log L, where L is the maximized value of the likelihood function used to obtain parameter estimates.","options":["Deviance","The pseudo-R2","The null deviation","The empty deviance"],"image":"assets/dta301/su24/30.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":6,"sourceTerm":"","detail":"Tên đại lượng trong định nghĩa −2 log L là deviance, theo cách chuẩn hóa dùng trong phần logistic của sách.","trick":"Deviance = âm hai log L.","why":["Đúng tên đại lượng được định nghĩa.","Pseudo-R² được suy ra bằng so residual và null deviance.","Null deviation không phải tên đại lượng tổng quát được định nghĩa.","Empty deviance không phải thuật ngữ output chuẩn ở đây."],"caution":"Công thức tổng quát của deviance so với saturated model là −2 log(Lfitted/Lsaturated); dạng rút gọn của đề dùng chuẩn hóa phù hợp.","topic":"Regression","gradable":true,"bookPage":183,"pdfPage":203,"slideNumbers":[43],"reference":"Sách chương 6, trang 183 (PDF trang 203) · Slides chương 6, slide 43","keywords":["logistic regression","−2 × log L"]},{"id":31,"stem":"Which of the following measures the purity of an attribute?","options":["Entropy","Information gain","Impurity rate","purity rate"],"image":"assets/dta301/su24/31.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":7,"sourceTerm":"purity of an attribute","detail":"Sách và slide phân biệt: Entropy đo impurity, Information gain đo mức tăng purity khi chia theo thuộc tính.","trick":"Entropy = hỗn tạp; Gain = được thêm độ thuần.","why":["Entropy đo impurity, không phải đáp án “purity” theo câu định nghĩa.","Đúng chỉ tiêu mà tài liệu gắn với purity.","Tên này nói về impurity và không phải thước đo được nêu.","Không phải tên chỉ tiêu chuẩn trong hai đại lượng đang học."],"caution":"Theo định nghĩa chương Classification, Entropy đo impurity, Information gain đo mức tăng purity. Entropy thấp cũng cho biết nút thuần hơn, nhưng đáp án của câu hỏi định nghĩa này là B.","topic":"Classification","gradable":true,"reference":"Sách chương 7, trang 197 (PDF trang 217) · Slide chương 7, slide 14","bookPage":197,"pdfPage":217,"slideNumbers":[14],"keywords":["purity","attribute"]},{"id":32,"stem":"Which of the following measures the impurity of an attribute?","options":["Entropy","Information gain","Impurity rate","purity rate"],"image":"assets/dta301/su24/32.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"","detail":"Entropy đo impurity, tức mức hỗn tạp lớp tại một nút/thuộc tính theo cách trình bày của chương.","trick":"Entropy cao = lẫn nhiều lớp; thấp = thuần.","why":["Đúng chỉ tiêu đo impurity.","Information gain đo giảm entropy/tăng độ thuần sau split.","Không phải tên thước đo mà tài liệu nêu trong cặp Entropy/Information gain.","Không phải tên chỉ tiêu chuẩn của phần này."],"caution":"","topic":"Classification","gradable":true,"bookPage":197,"pdfPage":217,"slideNumbers":[14],"reference":"Sách chương 7, trang 197 (PDF trang 217) · Slides chương 7, slide 14","keywords":["impurity","attribute"]},{"id":33,"stem":"A naive Bayes classifier assumes that the presence or absence of a particular feature of a class is related to the presence or absence of other features?","options":["True","False"],"image":"assets/dta301/su24/33.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":7,"sourceTerm":"independent","detail":"Naive Bayes giả định các đặc trưng độc lập có điều kiện khi biết lớp.","trick":"Naive = độc lập khi biết class.","why":["Sai vì câu nói “related” trái với giả định độc lập có điều kiện.","Đúng: phát biểu trong đề sai."],"caution":"Độc lập có điều kiện theo class, không nhất thiết độc lập vô điều kiện trong toàn bộ dữ liệu.","topic":"Classification","gradable":true,"reference":"Sách chương 7, trang 214 (PDF trang 234) · Slide chương 7, slide 45","bookPage":214,"pdfPage":234,"slideNumbers":[45],"keywords":["naive Bayes","feature","other features"]},{"id":34,"stem":"In a decision tree, ____ are the decision or test points.","options":["Internal nodes","Splits","Branches","Leaf nodes"],"image":"assets/dta301/su24/34.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"internal nodes","detail":"Internal nodes là các điểm kiểm tra/ra quyết định trong cây.","trick":"Node hỏi – branch đi – leaf trả lời.","why":["Đúng nơi kiểm tra một thuộc tính/điều kiện.","Split là thao tác chia tập, không phải tên loại nút.","Branch là nhánh ứng với kết quả phép kiểm tra.","Leaf là nơi đưa ra dự đoán cuối."],"caution":"","topic":"Classification","gradable":true,"reference":"Sách chương 7, trang 193 (PDF trang 213) · Slide chương 7, slide 7","bookPage":193,"pdfPage":213,"slideNumbers":[7],"keywords":["decision tree","decision or test points"]},{"id":35,"stem":"The process of converting continuous variables into categorical ones is called ____.","options":["discretization","specialization","separation","realization"],"image":"assets/dta301/su24/35.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":7,"sourceTerm":"discretization","detail":"Discretization chia miền giá trị liên tục thành các khoảng/nhãn rời rạc.","trick":"Discrete = rời rạc; tuổi số → nhóm tuổi.","why":["Đúng tên phép chuyển continuous sang categorical.","Specialization không phải tên chuyển đổi này.","Separation chỉ là từ chung, không phải thuật ngữ kỹ thuật được hỏi.","Realization không phải phép chia biến liên tục thành nhóm."],"caution":"","topic":"Classification","gradable":true,"reference":"Sách chương 7, trang 211 (PDF trang 231) · Slide chương 7, slide 39, 55","bookPage":211,"pdfPage":231,"slideNumbers":[39,55],"keywords":["continuous variables","categorical"]},{"id":36,"stem":"Which of the following refers to the long-term movement in a time series? It indicates whether the observation values are increasing or decreasing over time","options":["The trend component","The seasonality component","A cyclic component","The random component"],"image":"assets/dta301/su24/36.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":8,"sourceTerm":"","detail":"Trend là chuyển động dài hạn thể hiện mức tăng hoặc giảm theo thời gian.","trick":"Trend = xu hướng dài hạn.","why":["Đúng thành phần chuyển động dài hạn.","Seasonality là dao động theo chu kỳ cố định.","Cyclic là dao động lặp nhưng chu kỳ không cố định.","Random là phần nhiễu còn lại sau các thành phần có cấu trúc."],"caution":"","topic":"Time Series","gradable":true,"bookPage":235,"pdfPage":255,"slideNumbers":[5],"reference":"Sách chương 8, trang 235 (PDF trang 255) · Slides chương 8, slide 5","keywords":["long-term movement","time series"]},{"id":37,"stem":"is a useful model for addressing time series with non-constant variance or volatility. It is used for modeling stock market activity and price fluctuations.","options":["Autoregressive Moving Average with Exogenous inputs (ARMAX)","Spectral analysis","Generalized Autoregressive Conditionally Heteroscedastic (GARCH)","Kalman filtering","Multivariate time series analysis"],"image":"assets/dta301/su24/37.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[2],"chapter":8,"sourceTerm":"GARCH","detail":"GARCH mô hình hóa phương sai có điều kiện biến đổi và volatility, thường dùng cho tài chính.","trick":"GARCH = volatility/phương sai thay đổi.","why":["ARMAX thêm đầu vào ngoại sinh vào mô hình chuỗi.","Spectral analysis nghiên cứu thành phần tần số.","Đúng mô hình dành cho volatility thay đổi theo thời gian.","Kalman filter ước lượng trạng thái ẩn động.","Multivariate time series là mô hình nhiều chuỗi, không đặc trưng riêng cho volatility."],"caution":"","topic":"Time Series","gradable":true,"reference":"Sách chương 8, trang 253 (PDF trang 273) · Slide chương 8, slide 46","bookPage":253,"pdfPage":273,"slideNumbers":[46],"keywords":["non-constant variance","volatility"]},{"id":38,"stem":"Which of the following is NOT a steps in Box-Jenkins methodology for time series analysis?","options":["1. Condition data and select a model.","2. Estimate the model parameters.","3. Assess the model and return to Step 1, if necessary.","4, Gain the result from model and return to Step 1, if necessary."],"image":"assets/dta301/su24/38.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[3],"chapter":8,"sourceTerm":"Box","detail":"Box–Jenkins gồm chọn/nhận diện mô hình, ước lượng tham số, kiểm tra chẩn đoán và quay lại nếu cần.","trick":"Chọn – Ước lượng – Kiểm tra.","why":["Đúng bước chuẩn bị và nhận diện.","Đúng bước ước lượng.","Đúng bước chẩn đoán lặp lại nếu mô hình chưa đạt.","Không phải bước 4 riêng trong danh sách ba bước của tài liệu."],"caution":"","topic":"Time Series","gradable":true,"reference":"Sách chương 8, trang 235 (PDF trang 255) · Slide chương 8, slide 6","bookPage":235,"pdfPage":255,"slideNumbers":[6],"keywords":["NOT","Box-Jenkins"]},{"id":39,"stem":"Is the covariance correctly expressed by cov(yt, y(t+h)) = E[(yt − μt)(y(t+h) + μ(t+h))]?","options":["True","False"],"image":"assets/dta301/su24/39.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":8,"sourceTerm":"covariance","detail":"Biểu thức trong ảnh vẫn bằng covariance nếu các moment tồn tại. Đặt X=yt, Y=y(t+h). Vì E[X−μX]=0 nên E[(X−μX)(Y+μY)] = E[(X−μX)Y] = E[XY]−μXμY = Cov(X,Y). Công thức chuẩn trong sách thường viết dấu trừ ở cả hai ngoặc, nhưng đổi dấu của hằng số ở ngoặc thứ hai không làm đổi kỳ vọng khi ngoặc thứ nhất đã được centered.","trick":"Một thừa số đã trừ mean → kỳ vọng của nó bằng 0 → cộng/trừ hằng số ở thừa số kia không đổi covariance.","why":["Đúng về đại số: phần thêm hằng số triệt tiêu vì E[X−μX]=0.","Không thể kết luận sai chỉ vì có dấu cộng; hai biểu thức kỳ vọng tương đương, dù cách viết khác công thức chuẩn."],"caution":"Đáp án theo nghĩa toán học: A. Nếu key chấm B chỉ vì dấu cộng, key đó đã bỏ qua việc E[yt−μt]=0. Đối chiếu công thức chuẩn ở sách và phân tích đại số, không học máy móc dấu.","topic":"Time Series","gradable":true,"reference":"Sách chương 8, trang 236 (PDF trang 256) · Slide chương 8, slide 8","bookPage":236,"pdfPage":256,"slideNumbers":[8],"keywords":["covariance","(y(t+h) + μ(t+h))"]},{"id":40,"stem":"Which of the following analysis methods attempts to model the underlying structure of observations taken over time?","options":["Time series","Decision tree","Naive Bayes","Association rules"],"image":"assets/dta301/su24/40.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":8,"sourceTerm":"","detail":"Time series analysis mô hình hóa cấu trúc của các quan sát có thứ tự thời gian và phụ thuộc quá khứ.","trick":"Observations over time → time series.","why":["Đúng kỹ thuật cho dữ liệu tuần tự theo thời gian.","Decision tree phân chia theo điều kiện thuộc tính, không tự mô hình hóa cấu trúc thời gian.","Naive Bayes là bộ phân loại xác suất với giả định độc lập có điều kiện.","Association rules tìm quan hệ đồng xuất hiện giữa items."],"caution":"","topic":"Time Series","gradable":true,"bookPage":235,"pdfPage":255,"slideNumbers":[5,6],"reference":"Sách chương 8, trang 235 (PDF trang 255) · Slides chương 8, slide 5, 6","keywords":["underlying structure","observations taken over time"]},{"id":41,"stem":"Which of the following techniques use a given dictionary finds the correct dictionary base form of a word?","options":["Lemmatization methods","Stemming methods","Classification methods","Clustering methods"],"image":"assets/dta301/su24/41.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":9,"sourceTerm":"","detail":"Lemmatization dùng từ điển và ngữ cảnh ngữ pháp để tìm base form đúng của từ.","trick":"Lemma = từ gốc có nghĩa trong từ điển.","why":["Đúng phương pháp dictionary-based.","Stemming cắt affixes theo heuristic, có thể tạo stem không phải từ thật.","Classification gán nhãn văn bản/đối tượng.","Clustering gom nhóm theo tương đồng."],"caution":"","topic":"Text Analysis","gradable":true,"bookPage":258,"pdfPage":278,"slideNumbers":[7],"reference":"Sách chương 9, trang 258 (PDF trang 278) · Slides chương 9, slide 7","keywords":["dictionary","base form of a word"]},{"id":42,"stem":"Which of the following represents the weight of each term in a document, and it is proportional to the number of occurrences of the term in that document?","options":["Information content (IC)","Term frequency (TF)","Inverse Document Frequency (IDF)","Document Frequency (DF)"],"image":"assets/dta301/su24/42.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":9,"sourceTerm":"term frequency","detail":"TF đo số lần một term xuất hiện trong một tài liệu, có thể được chuẩn hóa.","trick":"TF: Tần suất trong 1 File.","why":["IC là độ thông tin/độ quan trọng xét theo corpus và ontology.","Đúng trọng số dựa trên số lần xuất hiện trong tài liệu.","IDF giảm khi từ xuất hiện ở nhiều tài liệu.","DF đếm số tài liệu chứa từ, không đếm số lần trong một tài liệu."],"caution":"","topic":"Text Analysis","gradable":true,"reference":"Sách chương 9, trang 265 (PDF trang 285) · Slide chương 9, slide 3, 15, 17","bookPage":265,"pdfPage":285,"slideNumbers":[3,15,17],"keywords":["weight of each term","number of occurrences"]},{"id":43,"stem":"Which of the followings is the process that takes unstructured text and imposes a structure for further analysis?","options":["Parsing","Search and retrieval","Text mining","Discover meaningful insights"],"image":"assets/dta301/su24/43.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":9,"sourceTerm":"","detail":"Parsing lấy văn bản phi cấu trúc và tạo cấu trúc/biểu diễn để xử lý tiếp.","trick":"Parse = tạo cấu trúc; Search = tìm; Mine = khai thác.","why":["Đúng định nghĩa bước parsing.","Search and retrieval tìm tài liệu phù hợp truy vấn sau khi có biểu diễn/index.","Text mining khai thác patterns/quan hệ từ terms và indexes.","Discover meaningful insights là mục tiêu, không phải tên thao tác tạo cấu trúc."],"caution":"","topic":"Text Analysis","gradable":true,"bookPage":257,"pdfPage":277,"slideNumbers":[6],"reference":"Sách chương 9, trang 257 (PDF trang 277) · Slides chương 9, slide 6","keywords":["unstructured text","imposes a structure"]},{"id":44,"stem":"Which of the followings uses the terms and indexes produced by the prior two steps to discover meaningful insights pertaining to domains or problems of interest?","options":["Parsing","Search and retrieval","Text mining","Discover meaningful insights"],"image":"assets/dta301/su24/44.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[2],"chapter":9,"sourceTerm":"uses the terms","detail":"Text mining dùng terms và indexes đã được tạo bởi parsing và search/retrieval để khám phá insight.","trick":"Terms + indexes → Mine để tìm insights.","why":["Parsing tạo biểu diễn/cấu trúc đầu vào.","Search and retrieval dùng cấu trúc để tìm tài liệu liên quan.","Đúng tên bước dùng đầu ra của hai bước trước.","Chỉ lặp lại mục tiêu “discover meaningful insights”, không phải tên bước theo định nghĩa."],"caution":"Discover meaningful insights là mục tiêu của Text mining; tên bước trong khung ba bước là Text mining.","topic":"Text Analysis","gradable":true,"reference":"Sách chương 9, trang 257 (PDF trang 277) · Slide chương 9, slide 6","bookPage":257,"pdfPage":277,"slideNumbers":[6],"keywords":["terms and indexes","discover meaningful insights"]},{"id":45,"stem":"Which of the following algorithms can process an input: “obesity causes many problems\" then the produce an output: “obes caus mani problem\"?","options":["Lemmatization","Stemming","Classification","Clustering"],"image":"assets/dta301/su24/45.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":9,"sourceTerm":"","detail":"Các kết quả obes, caus, mani không phải base words chuẩn từ điển: đây là Porter stemming cắt theo luật.","trick":"Gốc bị cụt, không cần là từ thật → stemming.","why":["Lemma thường cho obesity, cause, many, problem, không phải obes/mani.","Đúng ví dụ đầu ra Porter stemming trong slide.","Classification cho nhãn lớp, không cắt từ thành stem.","Clustering cho nhóm, không biến đổi hình thái từ như ví dụ."],"caution":"","topic":"Text Analysis","gradable":true,"bookPage":258,"pdfPage":278,"slideNumbers":[8],"reference":"Sách chương 9, trang 258 (PDF trang 278) · Slides chương 9, slide 8","keywords":["obesity causes many problems","obes caus mani problem"]},{"id":46,"stem":"What step in MapReduce applies an operation to a piece of data?","options":["Map","Reduce","Parsing"],"image":"assets/dta301/su24/46.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":10,"sourceTerm":"applies an operation","detail":"Map áp dụng phép xử lý cho từng phần dữ liệu đầu vào.","trick":"Map xử lý từng mảnh, Reduce gom kết quả.","why":["Đúng bước thao tác trên mỗi phần dữ liệu.","Reduce hợp nhất kết quả trung gian theo key.","Parsing là phân tích cú pháp/văn bản, không phải giai đoạn MapReduce đang hỏi."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"reference":"Sách chương 10, trang 298 (PDF trang 318) · Slide chương 10, slide 6","bookPage":298,"pdfPage":318,"slideNumbers":[6],"keywords":["MapReduce","applies an operation"]},{"id":47,"stem":"What step in MapReduce consolidates the intermediate outputs from the other steps and provides the final output?","options":["Map","Reduce","Gain insights","Parsing"],"image":"assets/dta301/su24/47.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":10,"sourceTerm":"Reduce","detail":"Reduce tổng hợp các output trung gian theo key để tạo output cuối.","trick":"Reduce gom kết quả Map.","why":["Map xử lý đầu vào và phát ra key/value trung gian.","Đúng giai đoạn consolidate output.","Gain insights là mục tiêu phân tích, không phải giai đoạn MapReduce.","Parsing là thao tác xử lý cú pháp/văn bản."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"reference":"Sách chương 10, trang 298 (PDF trang 318) · Slide chương 10, slide 6","bookPage":298,"pdfPage":318,"slideNumbers":[6],"keywords":["MapReduce","consolidates the intermediate outputs"]},{"id":48,"stem":"Which of the following will manage the data stored on each machine?","options":["The NameNode daemon","The DataNode daemon","The Secondary NameNode","The Third NameNode"],"image":"assets/dta301/su24/48.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":10,"sourceTerm":"","detail":"Mỗi DataNode quản lý và lưu các blocks trên máy của nó; NameNode giữ metadata/bản đồ block toàn cụm.","trick":"DataNode giữ data trên từng máy; NameNode giữ bản đồ.","why":["Quản lý metadata và vị trí block, không trực tiếp giữ mọi block dữ liệu của từng máy.","Đúng daemon quản lý block trên mỗi máy.","Secondary NameNode làm checkpoint metadata, không phải worker giữ blocks.","Không phải daemon HDFS chuẩn trong tài liệu."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"bookPage":301,"pdfPage":321,"slideNumbers":[12],"reference":"Sách chương 10, trang 301 (PDF trang 321) · Slides chương 10, slide 12","keywords":["manage the data","each machine"]},{"id":49,"stem":"In Apache Hadoop, ____ provides the logic to be processed on each data block corresponding to the specified input files in the driver code.","options":["The driver","The mapper","The scheduler","The combiner"],"image":"assets/dta301/su24/49.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":10,"sourceTerm":"mapper","detail":"Mapper cung cấp logic xử lý đầu vào/block được chỉ định bởi driver.","trick":"Driver chỉ đường; Mapper làm việc.","why":["Driver cấu hình job và tên các lớp/đường dẫn.","Đúng nơi cài logic map.","Scheduler phân phối lịch tài nguyên/task.","Combiner tổng hợp cục bộ đầu ra map khi thích hợp."],"caution":"","topic":"MapReduce và Hadoop","gradable":true,"reference":"Sách chương 10, trang 301 (PDF trang 321) · Slide chương 10, slide 14, 17","bookPage":301,"pdfPage":321,"slideNumbers":[14,17],"keywords":["Hadoop","logic","each data block"]},{"id":50,"stem":"The figure illustrates word-count processing in Apache Hadoop: Step 1 emits word/count pairs; Step 2 groups values by word; Step 3 sums counts. The three steps are ____.","options":["Map / Reduce / Shuffle and Sort","Map / Shuffle and Sort / Reduce","Reduce / Map / Shuffle and Sort","Reduce / Shuffle and Sort / Map"],"image":"assets/dta301/su24/50.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":10,"sourceTerm":"","detail":"Hình cho thấy Map phát cặp (word,1); Shuffle and Sort nhóm các giá trị theo word; Reduce cộng thành tần suất.","trick":"Phát cặp → gom key → cộng tổng = Map – Shuffle – Reduce.","why":["Đặt Reduce trước bước nhóm key nên không đúng hình.","Đúng thứ tự cả ba bước.","Đảo Map và Reduce.","Cả thứ tự đầu và cuối đều không khớp hình."],"caution":"Chú thích hình nói về combiner trong ví dụ Hadoop, nhưng thứ tự các thao tác được đánh số vẫn là Map, Shuffle and Sort, Reduce.","topic":"MapReduce và Hadoop","gradable":true,"bookPage":303,"pdfPage":323,"slideNumbers":[17,18,19],"reference":"Sách chương 10, trang 303 (PDF trang 323) · Slides chương 10, slide 17–18","keywords":["Step 1 emits","Step 2 groups","Step 3 sums"]},{"id":51,"stem":"The following statement will return: SELECT '123a567' ~ '^123a';","options":["True","False","Error","Empty"],"image":"assets/dta301/su24/51.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":11,"sourceTerm":"","detail":"Ký tự ^ neo regex vào đầu chuỗi. Chuỗi 123a567 bắt đầu bằng 123a nên khớp ^123a.","trick":"^ = đầu; $ = cuối.","why":["Đúng do prefix 123a nằm ngay đầu chuỗi.","Sai: không cần cả chuỗi bằng 123a vì không có neo cuối $.","Regex này hợp lệ.","Toán tử ~ trả boolean chứ không trả tập rỗng."],"caution":"Đã kiểm tra trực tiếp ảnh: ký tự đầu pattern là ^, không phải dấu * do OCR có thể đọc nhầm.","topic":"SQL và công cụ","gradable":true,"bookPage":340,"pdfPage":360,"slideNumbers":[13],"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slides chương 11, slide 13","keywords":["SELECT","'^123a'"]},{"id":52,"stem":"Which of the following function in PostgreSQL rank of the current row without gaps? This function counts peer groups.","options":["rank()","dense_rank()","percent_rank()","row_number()"],"image":"assets/dta301/su24/52.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":11,"sourceTerm":"dense_rank","detail":"DENSE_RANK cho thứ hạng không bỏ số sau các giá trị đồng hạng.","trick":"DENSE = dày liền: 1,1,2; RANK: 1,1,3.","why":["RANK có khoảng trống sau đồng hạng.","Đúng không gaps, đếm peer groups.","PERCENT_RANK là thứ hạng tương đối.","ROW_NUMBER đánh số riêng cho từng dòng, không cùng hạng cho peers."],"caution":"","topic":"SQL và công cụ","gradable":true,"reference":"Sách chương 11, trang 347 (PDF trang 367) · Slides chương 11","bookPage":347,"pdfPage":367,"slideNumbers":[],"keywords":["PostgreSQL","without gaps","peer groups"]},{"id":53,"stem":"The following statement will return: SELECT '123a567' ~ '23|b';","options":["True","False","Error","Nothing"],"image":"assets/dta301/su24/53.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":11,"sourceTerm":"Regular Expressions","detail":"Dấu | là OR. Pattern 23|b khớp chuỗi vì có đoạn con 23.","trick":"Regex | = hoặc; ~ không yêu cầu khớp cả chuỗi.","why":["Đúng vì có 23.","Không cần có cả 23 và b; chỉ một nhánh khớp là đủ.","Regex luân phiên này hợp lệ.","Kết quả của ~ là true/false, không phải Nothing."],"caution":"","topic":"SQL và công cụ","gradable":true,"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slide chương 11, slide 13","bookPage":340,"pdfPage":360,"slideNumbers":[13],"keywords":["SELECT","'23|b'"]},{"id":54,"stem":"The following statement will return: SELECT SUBSTRING('1234567890', 3, 2);","options":["34","23","Error","Empty"],"image":"assets/dta301/su24/54.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":11,"sourceTerm":"","detail":"SUBSTRING(string, start, count) lấy 2 ký tự bắt đầu tại vị trí 3. SQL đánh số từ 1 nên kết quả là chuỗi 34.","trick":"SQL từ 1: 1 2 [3 4].","why":["Đúng chuỗi gồm ký tự thứ 3 và 4.","23 tương ứng bắt đầu ở vị trí 2.","Cú pháp ba đối số này hợp lệ.","Chuỗi đủ dài để lấy dữ liệu; không rỗng."],"caution":"Kết quả là text “34”, không phải phép tính số 34.","topic":"SQL và công cụ","gradable":true,"bookPage":339,"pdfPage":359,"slideNumbers":[12,13],"reference":"Sách chương 11, trang 339 (PDF trang 359) · Slides chương 11, slide 12, 13","keywords":["SUBSTRING","3, 2"]},{"id":55,"stem":"The following statement will return: SELECT '123a567' ~ '27$';","options":["True","False","Error","Empty"],"image":"assets/dta301/su24/55.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[1],"chapter":11,"sourceTerm":"","detail":"27$ yêu cầu chuỗi kết thúc bằng 27. Chuỗi 123a567 kết thúc bằng 67, nên không khớp.","trick":"Nhìn $ rồi kiểm tra đuôi.","why":["Sai: chỉ có ký tự 7 ở cuối chưa đủ; cần cả 27.","Đúng false do suffix thực tế là 67.","Regex neo cuối hợp lệ.","~ trả boolean, không trả Empty."],"caution":"","topic":"SQL và công cụ","gradable":true,"bookPage":340,"pdfPage":360,"slideNumbers":[13],"reference":"Sách chương 11, trang 340 (PDF trang 360) · Slides chương 11, slide 13","keywords":["SELECT","'27$'"]},{"id":56,"stem":"Who typically tries to determine the benefits and implications of key project outputs of the findings to ‘the Business?","options":["Business users.","Project sponsor","Business Intelligence analyst","Data Scientists"],"image":"assets/dta301/su24/56.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":12,"sourceTerm":"benefits and implications","detail":"Business User quan tâm kết quả đem lại lợi ích và tác động gì cho nghiệp vụ.","trick":"User dùng kết quả; Sponsor xét ROI.","why":["Đúng mô tả Business User trong sách.","Sponsor chú trọng business impact, rủi ro và ROI.","BI Analyst xem tác động lên báo cáo/dashboard.","Data Scientist giải thích mô hình và code."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"reference":"Sách chương 12, trang 361 (PDF trang 381) · Slide chương 12, slide 6","bookPage":361,"pdfPage":381,"slideNumbers":[6],"keywords":["benefits and implications","Business"]},{"id":57,"stem":"Who typically need to share the code from the analytical project and create technical documents that describe how to implement the code at the conclusion of a project?","options":["Data Engineer and Database Administrator (DBA)","Business Intelligence Analyst","Project Manager","Business User"],"image":"assets/dta301/su24/57.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":12,"sourceTerm":"technical documents","detail":"Data Engineer và DBA cần chia sẻ code cùng tài liệu kỹ thuật mô tả cách triển khai.","trick":"Engineer/DBA = code chạy được + hướng dẫn triển khai.","why":["Đúng vai trò trong mục key outputs.","BI Analyst quan tâm báo cáo/dashboard.","Project Manager đánh giá tiến độ/ngân sách.","Business User quan tâm lợi ích nghiệp vụ."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"reference":"Sách chương 12, trang 362 (PDF trang 382) · Slides chương 12","bookPage":362,"pdfPage":382,"slideNumbers":[],"keywords":["share the code","technical documents"]},{"id":58,"stem":"Presentation for contains high-level takeaways for executive-level stakeholders, with a few key messages to aid their decision-making process?","options":["Project Sponsors","Analysts","Technical people","Database administrators"],"image":"assets/dta301/su24/58.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":12,"sourceTerm":"executive","detail":"Presentation for Project Sponsors ưu tiên thông điệp cấp cao, giá trị kinh doanh và hỗ trợ quyết định.","trick":"Sponsor cần quyết định; Analyst cần chi tiết.","why":["Đúng đối tượng executive-level.","Analyst cần chi tiết phương pháp, biến và kiểm định mô hình.","Technical people cần code và tài liệu triển khai.","DBA cần nội dung vận hành/dữ liệu, không phải bài trình bày executive."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"reference":"Sách chương 12, trang 362 (PDF trang 382) · Slide chương 12, slide 14, 16, 17","bookPage":362,"pdfPage":382,"slideNumbers":[14,16,17],"keywords":["high-level takeaways","executive-level stakeholders"]},{"id":59,"stem":"Which of the following section in of presentations for Project Sponsor we should discuss on Support key points with simple charts and graphics (example: bar charts)?","options":["Key Points Supported with Data","Model Details","Model Description","Main Findings"],"image":"assets/dta301/su24/59.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[0],"chapter":12,"sourceTerm":"","detail":"Key Points Supported with Data dành cho sponsor dùng biểu đồ đơn giản để hỗ trợ các thông điệp chính.","trick":"Key points + simple charts = Key Points Supported with Data.","why":["Khớp mô tả support key points với simple charts/graphics.","Model Details đi vào logic/code/biến mô hình hoặc được lược bỏ ở sponsor.","Model Description cho overview kỹ thuật mô hình.","Main Findings nêu thông điệp/phát hiện, không phải mục riêng trình bày dữ liệu hỗ trợ."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"bookPage":365,"pdfPage":385,"slideNumbers":[22],"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slides chương 12, slide 22","keywords":["Project Sponsor","Support key points","simple charts and graphics"]},{"id":60,"stem":"Which of the following section in of presentations for Project Sponsor we should discuss on overview of the modeling technique used in data analytics project?","options":["Key Points Supported with Data","Model Details","Model Description","Main Findings"],"image":"assets/dta301/su24/60.png","suppliedKey":null,"keyChanged":false,"multiple":false,"correct":[2],"chapter":12,"sourceTerm":"Model Description","detail":"Model Description cung cấp tổng quan kỹ thuật mô hình cho sponsor.","trick":"Description = mô tả tổng quan; Details = đào sâu.","why":["Key Points Supported with Data dùng biểu đồ hỗ trợ luận điểm.","Model Details có thể lược bỏ hoặc chỉ nói mức cao với sponsor.","Đúng phần overview of modeling technique.","Main Findings nhấn mạnh thông điệp/phát hiện chính."],"caution":"","topic":"Báo cáo và triển khai","gradable":true,"reference":"Sách chương 12, trang 365 (PDF trang 385) · Slide chương 12, slide 20, 21","bookPage":365,"pdfPage":385,"slideNumbers":[20,21],"keywords":["Project Sponsor","overview of the modeling technique"]}],"subject":"dta301","legacyExamId":"su24"}});